package com.example.cvd;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.ss.usermodel.CellType;
import java.nio.file.*;
import java.time.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class ReportTest {
 ObjectMapper json=new ObjectMapper();@TempDir Path dir;
 ObjectNode snapshot(){var s=json.createObjectNode().put("language","zh-TW").put("start","2026-10-03T00:00:00Z").put("end","2026-10-03T01:00:00Z").put("resolutionSeconds",60).put("phmResolutionSeconds",60).put("simulated",true);var eq=s.putArray("equipment").addObject().put("equipmentId",Equipment.FIRST).put("coverage",100);eq.putObject("states").put("processing",3000).put("idle",600).put("unknown",0);eq.putObject("production").put("completed",25).put("scrapped",1).put("dummyCompleted",4).put("dummyScrapped",0).put("coverage",99).put("quality","partial");eq.putObject("utilization").put("utilization",83.33).put("pmUtilization",50);var time=eq.putArray("timeline").addObject().put("start",s.path("start").asText()).put("end",s.path("end").asText()).put("state","mixed");time.putArray("flags").add(0);time.set("states",eq.get("states"));var k=s.putArray("kla").addObject().put("id","k1").put("equipmentId",Equipment.FIRST).put("waferId","=HYPERLINK(\"malicious\")").put("revision",2).put("completedAt","2026-10-03T00:30:00Z").put("meanNm",10.1).put("uniformityPct",1.4).put("purpose","dummy").put("synthetic",true).put("thicknessQuality","pass");var v=s.putArray("vision").addObject().put("id","j1").put("waferId","w1").put("quality","review").put("defectCount",3).put("mode","dataset-replay");v.putArray("candidates").add("scratch");var pump=s.putArray("phm").addObject().put("equipmentId",Equipment.FIRST).putArray("pumps").addObject().put("pumpId","LL1").put("passRate",100);pump.putObject("lastHistorical").put("time","2026-10-03T00:30:00Z").put("health",99).put("remainingCycles",800);pump.putObject("counts").put("passed",3).put("failed",0).put("interrupted",1);pump.putArray("trend").addObject().put("epoch",1790987400).put("health",99).put("samples",5);s.putArray("pending").addObject().put("equipmentId",Equipment.FIRST).put("kla",0).put("vision",1);s.putArray("sources").addObject().put("source","fixture").put("capturedAt",Instant.now().toString());ReportData.buildMetrics(s);return s;}
 ObjectNode answer(){var a=json.createObjectNode();var sections=a.putArray("sections");for(String title:List.of("產出","量測","資料說明")){var p=sections.addObject().put("title",title).put("text","模擬量測膜厚為 {{kla.meanNm}}，請人工核對來源。資料不足不作零值判定。");p.putArray("refs").add("kla.meanNm");}var charts=a.putArray("charts");ReportAi.CHARTS.forEach((k,v)->charts.addObject().put("dataset",k).put("type",v));return a;}
 ReportAi ai(String key,String model,String url,int seconds){return new ReportAi(json,"",key,model,url,seconds);}
 @Test void boundariesAndScope(){Instant end=Instant.parse("2026-10-02T16:30:00Z");assertEquals(Instant.parse("2026-10-02T16:00:00Z"),ReportData.start("today",end));for(String period:List.of("24h","7d","30d"))assertTrue(ReportData.start(period,end).isBefore(end));assertEquals(10,ReportData.equipment("all").size());assertThrows(Exception.class,()->ReportData.equipment("invalid"));assertThrows(Exception.class,()->ReportData.start("year",end));}
 @Test void rejectsInventedReferencesNumbersCausesAndCharts(){var ai=ai("key","fixture","http://127.0.0.1",1);assertEquals(3,ai.validate(answer(),snapshot()).path("sections").size());for(String bad:List.of("稼動率 99.2%","根因為真空洩漏","Due to pump failure","TEL-CVDTIN-08A-11","three wafers")){var a=answer();((ObjectNode)a.path("sections").get(0)).put("text",bad);assertThrows(ReportFailure.class,()->ai.validate(a,snapshot()),bad);}var a=answer();((ArrayNode)a.path("sections").get(0).path("refs")).add("missing.metric");final var badRef=a;assertThrows(ReportFailure.class,()->ai.validate(badRef,snapshot()));a=answer();((ObjectNode)a.path("charts").get(0)).put("dataset","execute-code");final var badChart=a;assertThrows(ReportFailure.class,()->ai.validate(badChart,snapshot()));}
 @Test void minimalPayloadAndNoKey(){var ai=ai("secret","fixture","https://api.openai.com/v1/responses",1);var input=ai.input(snapshot()).toString();for(String privateField:List.of("password","username","email","HYPERLINK","secret","waferId"))assertFalse(input.contains(privateField));assertThrows(ReportFailure.class,()->ai("","","http://127.0.0.1",1).analyze(snapshot()));}
 @Test void immutableSnapshotExcelAndThreeLanguages()throws Exception{for(String lang:List.of("zh-TW","en","ja")){var s=snapshot();s.put("language",lang);var ai=ai("key","fixture","http://127.0.0.1",1);var analysis=ai.validate(answer(),s);analysis.put("model","fixture").put("promptVersion",ReportAi.PROMPT_VERSION);var path=dir.resolve(lang);var manifest=new ReportRenderer(json).render(path,s,analysis,"fixture");assertEquals(ReportData.hash(s),manifest.path("snapshotHash").asText());try(var book=new XSSFWorkbook(Files.newInputStream(path.resolve("report.xlsx")))){assertEquals(8,book.getNumberOfSheets());assertEquals(6,book.getAllPictures().size());assertEquals(CellType.NUMERIC,book.getSheetAt(1).getRow(1).getCell(4).getCellType());assertEquals(25,book.getSheetAt(1).getRow(1).getCell(4).getNumericCellValue());assertEquals(CellType.STRING,book.getSheetAt(3).getRow(1).getCell(1).getCellType());assertTrue(book.getSheetAt(3).getRow(1).getCell(1).getStringCellValue().startsWith("=HYPERLINK"));assertEquals(analysis.path("sections").get(0).path("text").asText(),book.getSheetAt(0).getRow(6).getCell(0).getStringCellValue());}for(String ds:ReportAi.CHARTS.keySet())assertTrue(Files.size(path.resolve(ds+".png"))>1000);}
 var fixture=Path.of("target/report-fixture");var s=snapshot();var analysis=ai("key","fixture","http://127.0.0.1",1).validate(answer(),s);analysis.put("model","fixture").put("promptVersion",ReportAi.PROMPT_VERSION);new ReportRenderer(json).render(fixture,s,analysis,"fixture");}
 @Test void apiRetryRefusalAndRequestSchema()throws Exception{var calls=new AtomicInteger();var mode=new AtomicInteger(0);var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/responses",exchange->{try{calls.incrementAndGet();var body=json.readTree(exchange.getRequestBody());assertFalse(body.path("store").asBoolean(true));assertEquals("json_schema",body.path("text").path("format").path("type").asText());assertTrue(body.path("text").path("format").path("strict").asBoolean());String response;int status;if(mode.get()==0){status=503;response="{}";}else if(mode.get()==1){status=200;var n=json.createObjectNode().put("status","completed");n.putArray("output").addObject().putArray("content").addObject().put("type","output_text").put("text",answer().toString());response=n.toString();}else{status=200;response="{\"status\":\"completed\",\"output\":[{\"content\":[{\"type\":\"refusal\"}]}]}";}byte[] bytes=response.getBytes();exchange.sendResponseHeaders(status,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();}catch(Exception e){throw new RuntimeException(e);}});server.start();try{var api=ai("test-key","fixture","http://127.0.0.1:"+server.getAddress().getPort()+"/responses",2);assertEquals("ai-unavailable",assertThrows(ReportFailure.class,()->api.analyze(snapshot())).code);assertEquals(3,calls.get());mode.set(1);assertEquals(3,api.analyze(snapshot()).path("sections").size());mode.set(2);assertEquals("ai-refused",assertThrows(ReportFailure.class,()->api.analyze(snapshot())).code);}finally{server.stop(0);}}
 @Test void transportTimeoutAndIncompleteFormat()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var executor=java.util.concurrent.Executors.newCachedThreadPool();server.setExecutor(executor);var mode=new AtomicInteger();server.createContext("/responses",exchange->{try{if(mode.get()==0)Thread.sleep(1300);byte[] bytes=(mode.get()==1?"{\"status\":\"incomplete\"}":"not-json").getBytes();exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);}catch(Exception ignored){}finally{exchange.close();}});server.start();try{var api=ai("test","fixture","http://127.0.0.1:"+server.getAddress().getPort()+"/responses",1);assertEquals("ai-timeout",assertThrows(ReportFailure.class,()->api.analyze(snapshot())).code);mode.set(1);assertEquals("ai-incomplete",assertThrows(ReportFailure.class,()->api.analyze(snapshot())).code);mode.set(2);assertEquals("ai-invalid",assertThrows(ReportFailure.class,()->api.analyze(snapshot())).code);}finally{server.stop(0);executor.shutdownNow();}}
 @Test void rowAndFileLimits()throws Exception {var r=new ReportRenderer(json);assertTrue(r.chartFont.canDisplay('晶'));assertTrue(r.chartFont.canDisplay('語'));var stream=new ReportRenderer.BoundedOutput(java.io.OutputStream.nullOutputStream());byte[] chunk=new byte[1024*1024];for(int i=0;i<50;i++)stream.write(chunk,0,chunk.length);assertThrows(ReportFailure.class,()->stream.write(0));try(var book=new XSSFWorkbook()){var sheet=book.createSheet();assertThrows(ReportFailure.class,()->ReportRenderer.row(sheet,"x".repeat(32701)));}var s=snapshot();assertTrue(r.chartSeries("kla",s).size()<=360);}
}
